'use client'

import { useEffect, useState, useCallback } from 'react'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import LanguageToggle from '@/components/LanguageToggle'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ComplaintModal from '@/components/consumer/ComplaintModal'
import OrderFeedbackModal from '@/components/consumer/OrderFeedbackModal'
import OrderCard, { ConsumerOrder as Order, isResolved, isCompleted } from '@/components/consumer/OrderCard'

export default function ConsumerOrdersPage() {
  const { tx, L } = useLang()
  const { state, openAuth } = useConsumerAuth()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  // Order code the complaint modal is pinned to ('' means a general complaint
  // with no preset). null means the modal is closed.
  const [complaintFor, setComplaintFor] = useState<string | null>(null)
  // Order the feedback sheet is open for (null = closed).
  const [feedbackFor, setFeedbackFor] = useState<Order | null>(null)

  const refresh = useCallback(async () => {
    setLoading(true)
    setError('')
    const r = await fetch('/api/consumer/orders', { credentials: 'same-origin' }).catch(() => null)
    if (!r) { setError('Could not load orders. Check your connection.'); setLoading(false); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load orders.'); setLoading(false); return }
    setOrders((json.orders ?? []) as Order[])
    setLoading(false)
  }, [])

  useEffect(() => {
    if (state.status === 'authenticated') {
      void refresh()
    } else if (state.status === 'anonymous') {
      setLoading(false)
    }
  }, [state.status, refresh])

  // Active orders only — resolved ones (delivered / picked up / received /
  // declined / cancelled) live on the separate history page to cut clutter.
  const activeOrders = orders.filter((o) => !isResolved(o))
  const completedCount = orders.length - activeOrders.length

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <div className="flex items-center justify-between mb-4">
          <Link href="/consumer" className="text-green-300 text-sm flex items-center gap-1">
            {L('← Back', '← వెనక్కు')}
          </Link>
          <LanguageToggle />
        </div>
        <h1 className="text-white text-xl font-extrabold leading-tight">{tx.myOrders}</h1>
        <p className="text-green-400 text-sm mt-1">
          {L('Your orders in progress', 'మీ ప్రస్తుత ఆర్డర్‌లు')}
        </p>
      </div>

      <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
        {/* Active | History switcher — two separate pages, shown side by side
            so finished orders are one tap away without cluttering this list. */}
        {state.status === 'authenticated' && !error && (
          <div className="bg-white rounded-2xl border border-gray-100 p-1.5 flex gap-1.5">
            <span className="flex-1 py-2.5 rounded-xl text-xs font-bold text-center bg-green-700 text-white">
              {L('Active', 'ప్రస్తుత')} ({activeOrders.length})
            </span>
            <Link
              href="/consumer/orders/history"
              className="flex-1 py-2.5 rounded-xl text-xs font-bold text-center bg-gray-50 text-gray-600 active:bg-gray-100"
            >
              {L('History', 'చరిత్ర')}{completedCount > 0 ? ` (${completedCount})` : ''}
            </Link>
          </div>
        )}

        {state.status === 'loading' || loading ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center text-sm text-gray-500">
            {L('Loading...', 'లోడ్ అవుతోంది')}
          </div>
        ) : state.status === 'anonymous' ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-4">
            <div className="text-5xl">🔒</div>
            <div>
              <p className="font-bold text-gray-900">
                {L('Log in to see your orders', 'మీ ఆర్డర్‌లు చూడటానికి లాగిన్ అవ్వండి')}
              </p>
            </div>
            <button
              onClick={openAuth}
              className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
            >
              {L('Log in', 'లాగిన్')}
            </button>
          </div>
        ) : error ? (
          <div className="bg-white rounded-2xl border border-red-100 p-6 space-y-3">
            <p className="text-sm text-red-600">{error}</p>
            <button
              onClick={() => void refresh()}
              className="text-sm font-bold text-green-700 underline"
            >
              {L('Try again', 'మళ్లీ ప్రయత్నించండి')}
            </button>
          </div>
        ) : orders.length === 0 ? (
          <div className="text-center py-14">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noOrdersYet}</p>
            <Link href="/consumer" className="mt-4 inline-block text-green-700 text-sm underline font-semibold">
              {L('Browse produce →', 'పంట చూడండి →')}
            </Link>
          </div>
        ) : (
          <div className="space-y-3">
            {activeOrders.length === 0 ? (
              <div className="text-center py-12">
                <div className="text-4xl mb-2">🧺</div>
                <p className="font-semibold text-gray-500 text-sm">
                  {L('No active orders', 'ప్రస్తుత ఆర్డర్‌లు లేవు')}
                </p>
                <Link href="/consumer" className="mt-3 inline-block text-green-700 text-sm underline font-semibold">
                  {L('Browse produce →', 'పంట చూడండి →')}
                </Link>
              </div>
            ) : (
              activeOrders.map((order) => (
                <OrderCard key={order.id} order={order} onComplaint={setComplaintFor} onFeedback={setFeedbackFor} />
              ))
            )}
          </div>
        )}

        <Link
          href="/consumer/complaints"
          className="mt-6 block text-center text-xs font-semibold text-green-700 underline"
        >
          🛟 {L('My complaints', 'నా ఫిర్యాదులు')}
        </Link>

        <Link
          href="/buyer-protection"
          className="mt-3 block text-center text-xs font-semibold text-green-700 underline"
        >
          🔒 {L('Buyer protection & refund policy', 'కొనుగోలుదారు రక్షణ & రీఫండ్ విధానం')}
        </Link>
      </div>

      {complaintFor !== null && (
        <ComplaintModal
          presetOrderCode={complaintFor || null}
          onClose={() => setComplaintFor(null)}
          onCreated={() => setComplaintFor(null)}
        />
      )}

      {feedbackFor && (
        <OrderFeedbackModal
          orderId={feedbackFor.id}
          produceName={feedbackFor.produce_name}
          completed={isCompleted(feedbackFor)}
          existing={feedbackFor.my_review ?? null}
          onClose={() => setFeedbackFor(null)}
          onSaved={() => { setFeedbackFor(null); void refresh() }}
        />
      )}
    </main>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import LanguageToggle from '@/components/LanguageToggle'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ComplaintModal from '@/components/consumer/ComplaintModal'
import ProduceReviewBox, { type MyReview } from '@/components/consumer/ProduceReviewBox'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

type Order = {
  id: string
  order_code: string | null
  produce_name: string | null
  produce_listing_id?: string | null
  my_review?: MyReview | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method: string | null
  payment_method_detail?: string | null
  payment_status: string | null
  paid_at?: string | null
  confirmed_at?: string | null
  razorpay_payment_id: string | null
  refund_status: string | null
  refund_id: string | null
  refund_amount: number | null
  refunded_at: string | null
  decline_reason: string | null
  payment_proof_path: string | null
  created_at: string
  farmer_id: string
  farmer?: {
    name: string
    slug: string
    village: string
    phone: string | null
    upi_id: string | null
  } | null
  delivery_type?: 'self_pickup' | 'home_delivery' | 'courier' | null
  delivery_status?: DeliveryStatus | null
  delivery_address?: string | null
  delivery_landmark?: string | null
  delivery_pincode?: string | null
  delivery_alt_phone?: string | null
  handover_otp?: string | null
  assigned_at?: string | null
  picked_up_at?: string | null
  out_for_delivery_at?: string | null
  delivered_at?: string | null
  collected_at?: string | null
  shipped_at?: string | null
  received_at?: string | null
  fulfillment_date?: string | null
  rider?: { id: string; name: string | null; phone: string } | null
}

// Online payments go through Razorpay (stored as payment_method 'razorpay';
// some legacy orders use 'upi'). The real instrument the buyer used — PhonePe /
// Google Pay / UPI / Card — is resolved into payment_method_detail after the
// payment is verified. Never surface the gateway name "razorpay" to the buyer.
function isOnlinePayment(method: string | null | undefined): boolean {
  return method === 'razorpay' || method === 'upi'
}

export default function OrderDetailsPage() {
  const params = useParams<{ id: string }>()
  const id = typeof params?.id === 'string' ? params.id : ''
  const { state, openAuth } = useConsumerAuth()
  const { tx, L, lang } = useLang()
  const [order, setOrder] = useState<Order | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [proofUrl, setProofUrl] = useState<string | null>(null)
  const [proofLoading, setProofLoading] = useState(false)
  const [showReceipt, setShowReceipt] = useState(false)
  const [cancelling, setCancelling] = useState(false)
  const [showComplaint, setShowComplaint] = useState(false)
  const [confirmingReceipt, setConfirmingReceipt] = useState(false)

  // Buyer may cancel only while still pending and within 30 min of placing.
  const canCancel = !!order
    && order.status === 'pending'
    && !!order.created_at
    && Date.now() - new Date(order.created_at).getTime() < 30 * 60 * 1000

  // A home delivery is rider-driven once a rider is assigned (or its delivery
  // status moved past 'unassigned'). Those keep the rider tracking panel;
  // home deliveries with no rider are farmer-shipped (Shipped → Received).
  const riderAssigned = !!order
    && order.delivery_type === 'home_delivery'
    && (!!order.rider || (order.delivery_status != null && order.delivery_status !== 'unassigned'))

  // A shipped order (courier, or a farmer-shipped home delivery) awaits the
  // buyer's "Received" confirmation. Rider deliveries never set shipped_at, so
  // they're naturally excluded; self-pickup is gated out explicitly.
  const canConfirmReceipt = !!order
    && order.delivery_type !== 'self_pickup'
    && !!order.shipped_at
    && !order.received_at

  const handleCancel = async () => {
    if (!order) return
    if (!window.confirm(L('Cancel this order? If you have already paid, you will be refunded automatically.', 'ఈ ఆర్డర్‌ను రద్దు చేయాలా? మీరు ఇప్పటికే చెల్లించి ఉంటే, డబ్బు ఆటోమేటిక్‌గా తిరిగి వస్తుంది.'))) return
    setCancelling(true)
    try {
      const res = await fetch(`/api/consumer/orders/${order.id}/cancel`, {
        method: 'POST',
        credentials: 'same-origin',
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) { alert(json.error || L('Could not cancel the order.', 'ఆర్డర్ రద్దు చేయలేకపోయాం.')); return }
      // Refresh the order so status + any refund show up.
      const r = await fetch(`/api/consumer/orders/${order.id}`, { credentials: 'same-origin' })
      const fresh = await r.json().catch(() => ({}))
      if (r.ok && fresh.order) setOrder(fresh.order as Order)
    } catch {
      alert(L('Network error. Please try again.', 'నెట్‌వర్క్ సమస్య. మళ్ళీ ప్రయత్నించండి.'))
    } finally {
      setCancelling(false)
    }
  }

  const handleConfirmReceipt = async () => {
    if (!order) return
    if (!window.confirm(L('Confirm you received this order?', 'మీరు ఈ ఆర్డర్‌ను అందుకున్నారా?'))) return
    setConfirmingReceipt(true)
    try {
      const res = await fetch(`/api/consumer/orders/${order.id}/received`, {
        method: 'POST',
        credentials: 'same-origin',
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) { alert(json.error || L('Could not confirm receipt.', 'అందుకున్నట్టు ధృవీకరించలేకపోయాం.')); return }
      const r = await fetch(`/api/consumer/orders/${order.id}`, { credentials: 'same-origin' })
      const fresh = await r.json().catch(() => ({}))
      if (r.ok && fresh.order) setOrder(fresh.order as Order)
    } catch {
      alert(L('Network error. Please try again.', 'నెట్‌వర్క్ సమస్య. మళ్ళీ ప్రయత్నించండి.'))
    } finally {
      setConfirmingReceipt(false)
    }
  }

  useEffect(() => {
    if (state.status !== 'authenticated' || !id) {
      if (state.status === 'anonymous') setLoading(false)
      return
    }
    let cancelled = false
    setLoading(true)
    setError('')
    fetch(`/api/consumer/orders/${id}`, { credentials: 'same-origin' })
      .then(async (r) => {
        const json = await r.json().catch(() => ({}))
        if (cancelled) return
        if (!r.ok) {
          setError(json?.error ?? 'Could not load order.')
          setLoading(false)
          return
        }
        setOrder(json.order as Order)
        setLoading(false)
      })
      .catch(() => {
        if (cancelled) return
        setError('Network error. Please try again.')
        setLoading(false)
      })
    return () => { cancelled = true }
  }, [id, state.status])

  // The order is "done" once it reaches a terminal state — live polling stops
  // there so we're not hitting the API for an order that can't change anymore.
  const orderDone = !!order && (
    order.status === 'declined'
    || order.status === 'cancelled'
    || !!order.received_at
    || !!order.collected_at
    || order.delivery_status === 'delivered'
  )
  const orderActive = !!order && !orderDone && (order.status === 'pending' || order.status === 'approved')

  // Live tracking. While the order screen is open and the order is still active,
  // re-fetch every 5s so a farmer/rider action (Shipped, Picked Up, Out for
  // delivery…) advances the on-screen timeline almost immediately — and
  // re-fetch the moment the buyer brings the tab back into focus. The fetch goes
  // through the same secure, ownership-checked API route as the first load; no
  // notifications, just the tracker updating itself on screen.
  useEffect(() => {
    if (!orderActive || !id || state.status !== 'authenticated') return

    const silentRefresh = () => {
      fetch(`/api/consumer/orders/${id}`, { credentials: 'same-origin' })
        .then(async (r) => {
          if (!r.ok) return
          const json = await r.json().catch(() => ({}))
          if (json.order) setOrder(json.order as Order)
        })
        .catch(() => {})
    }

    const timer = setInterval(silentRefresh, 5000)
    const onVisible = () => { if (document.visibilityState === 'visible') silentRefresh() }
    document.addEventListener('visibilitychange', onVisible)
    window.addEventListener('focus', silentRefresh)

    return () => {
      clearInterval(timer)
      document.removeEventListener('visibilitychange', onVisible)
      window.removeEventListener('focus', silentRefresh)
    }
  }, [orderActive, id, state.status])

  // Resolve a fresh signed URL for the payment screenshot
  useEffect(() => {
    if (!order?.payment_proof_path) { setProofUrl(null); return }
    let cancelled = false
    setProofLoading(true)
    fetch(`/api/orders/${order.id}/proof`, { credentials: 'same-origin' })
      .then(async (r) => {
        const json = await r.json().catch(() => ({}))
        if (cancelled) return
        setProofUrl(typeof json?.url === 'string' ? json.url : null)
        setProofLoading(false)
      })
      .catch(() => { if (!cancelled) setProofLoading(false) })
    return () => { cancelled = true }
  }, [order?.id, order?.payment_proof_path])

  const statusColor = (s: string) =>
    s === 'approved' ? 'bg-green-100 text-green-800'
      : s === 'declined' ? 'bg-red-100 text-red-700'
      : s === 'cancelled' ? 'bg-gray-200 text-gray-700'
      : 'bg-amber-100 text-amber-800'

  const statusLabel = (s: string) =>
    s === 'approved' ? tx.statusConfirmed
      : s === 'declined' ? tx.statusDeclined
      : s === 'cancelled' ? tx.statusCancelled
      : tx.statusPending

  const paymentLabel = (o: Order) => {
    if (o.payment_method === 'cod') return L('Cash on Delivery', 'నగదు చెల్లింపు')
    if (isOnlinePayment(o.payment_method)) {
      // Show the real method (PhonePe / Google Pay / UPI…) once we know it,
      // instead of the gateway name. Falls back to "UPI" before it resolves.
      const m = o.payment_method_detail || 'UPI'
      if (o.payment_status === 'paid' || o.payment_status === 'completed') return `${m} ✓ Paid`
      if (o.payment_status === 'pending_confirmation' || o.payment_status === 'payment_claimed')
        return `${m} ⏳ Awaiting farmer confirmation`
      if (o.payment_status === 'failed') return `${m} ✕ Not received`
      return `${m} · Pending`
    }
    return o.payment_method ?? '—'
  }

  const orderDate = order
    ? new Date(order.created_at).toLocaleDateString('en-IN', {
        day: 'numeric', month: 'short', year: 'numeric',
      })
    : ''
  const orderTime = order
    ? new Date(order.created_at).toLocaleTimeString('en-IN', {
        hour: '2-digit', minute: '2-digit',
      })
    : ''

  const whatsappHref = order?.farmer?.phone && order?.produce_name
    ? `https://wa.me/91${order.farmer.phone.replace(/\D/g, '').slice(-10)}?text=${encodeURIComponent(
        `Hello ${order.farmer.name} anna, regarding my order of ${order.produce_name} on ${orderDate}.`,
      )}`
    : null

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <div className="flex items-center justify-between mb-4">
          <Link href="/consumer/orders" className="text-green-300 text-sm flex items-center gap-1">
            ← {L('Back', 'వెనక్కు')}
          </Link>
          <LanguageToggle />
        </div>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {L('Order details', 'ఆర్డర్ వివరాలు')}
        </h1>
      </div>

      <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
        {state.status === 'anonymous' ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-4">
            <div className="text-5xl">🔒</div>
            <p className="font-bold text-gray-900">Log in to view this order</p>
            <button
              onClick={openAuth}
              className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
            >
              {L('Log in', 'లాగిన్')}
            </button>
          </div>
        ) : loading ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center text-sm text-gray-500">
            {L('Loading...', 'లోడ్ అవుతోంది')}
          </div>
        ) : error ? (
          <div className="bg-white rounded-2xl border border-red-100 p-6 text-sm text-red-600">{error}</div>
        ) : !order ? null : (
          <>
            {/* Status + payment summary */}
            <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Order</p>
                  {order.order_code && (
                    <p className="text-[11px] font-mono font-semibold text-gray-400">{order.order_code}</p>
                  )}
                  <p className="text-base font-extrabold text-gray-900 leading-tight">
                    {localizeName(order.produce_name, lang) || '—'}
                  </p>
                  <p className="text-xs text-gray-500 mt-0.5">
                    {order.quantity} {order.unit || 'kg'}
                    {order.total_price ? ` · ₹${order.total_price}` : ''}
                  </p>
                </div>
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusColor(order.status)}`}>
                  {statusLabel(order.status)}
                </span>
              </div>

              <div className="grid grid-cols-2 gap-3 pt-1 border-t border-gray-100 mt-3">
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Placed</p>
                  <p className="text-xs font-semibold text-gray-700">{orderDate}</p>
                  <p className="text-[11px] text-gray-500">{orderTime}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Payment</p>
                  <p className="text-xs font-semibold text-gray-700">{paymentLabel(order)}</p>
                </div>
              </div>

              {order.pickup_location && (
                <div className="pt-1 border-t border-gray-100 mt-1">
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Pickup</p>
                  <p className="text-xs font-semibold text-gray-700">📍 {order.pickup_location}</p>
                </div>
              )}

              {(order.payment_status === 'paid' || order.payment_status === 'completed') && (
                <button
                  onClick={() => setShowReceipt(true)}
                  className="mt-3 w-full border border-green-600 text-green-700 font-bold py-2.5 rounded-xl text-sm active:bg-green-50"
                >
                  🧾 {L('View receipt', 'రసీదు చూడండి')}
                </button>
              )}

              {canCancel && (
                <button
                  onClick={handleCancel}
                  disabled={cancelling}
                  className="mt-2 w-full border border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
                >
                  {cancelling ? L('Cancelling...', 'రద్దు చేస్తోంది...') : L('✕ Cancel order', 'ఆర్డర్ రద్దు (30 min లోపు)')}
                </button>
              )}

              {canConfirmReceipt && (
                <button
                  onClick={handleConfirmReceipt}
                  disabled={confirmingReceipt}
                  className="mt-3 w-full bg-green-600 text-white font-bold py-3 rounded-xl text-sm active:bg-green-700 disabled:opacity-50"
                >
                  {confirmingReceipt ? '…' : L('✓ Received', 'అందుకున్నాను')}
                </button>
              )}
            </div>

            {/* Pickup / Delivery date the farmer scheduled for this order. */}
            {order.fulfillment_date && order.status !== 'declined' && order.status !== 'cancelled' && (
              <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center gap-3">
                <span className="text-2xl">📅</span>
                <div>
                  <p className="text-[10px] font-bold text-green-700 uppercase tracking-wide">
                    {order.delivery_type === 'home_delivery'
                      ? L('Delivery date', 'డెలివరీ తేదీ')
                      : L('Pickup date', 'పికప్ తేదీ')}
                  </p>
                  <p className="text-sm font-extrabold text-green-900 mt-0.5">
                    {new Date(`${order.fulfillment_date}T00:00:00`).toLocaleDateString('en-IN', {
                      weekday: 'short', day: 'numeric', month: 'short', year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
            )}

            {/* Rider tracking + handover OTP — only for rider-driven home
                deliveries (a rider is assigned). */}
            {riderAssigned && order.status !== 'declined' && (
              <DeliveryPanel order={order} />
            )}

            {/* Status timeline for everything else: self-pickup, courier, and
                farmer-shipped home deliveries (Shipped → Received). */}
            {!riderAssigned && order.status !== 'declined' && (
              <OrderStatusPanel order={order} />
            )}

            {/* Rate the produce — only once the order is completed. */}
            {order.produce_listing_id
              && order.status !== 'declined'
              && order.status !== 'cancelled'
              && (!!order.received_at || !!order.collected_at || !!order.delivered_at || order.delivery_status === 'delivered') && (
              <ProduceReviewBox
                orderId={order.id}
                produceName={order.produce_name ? localizeName(order.produce_name, lang) : L('this produce', 'ఈ ఉత్పత్తి')}
                existing={order.my_review ?? null}
              />
            )}

            {/* Decline reason */}
            {order.status === 'declined' && order.decline_reason && (
              <div className="bg-red-50 border border-red-200 rounded-2xl p-4">
                <p className="text-xs font-bold text-red-700 uppercase tracking-wide">{L('Decline reason', 'కారణం')}</p>
                <p className="text-sm text-red-800 mt-1 leading-snug">{order.decline_reason}</p>
              </div>
            )}

            {/* Refund status — shown whenever a refund exists for this order */}
            {order.refund_status && <RefundPanel order={order} />}

            {/* Payment screenshot */}
            {order.payment_method === 'upi' && (
              <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-2">
                <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
                  {L('Payment screenshot', 'చెల్లింపు స్క్రీన్‌షాట్')}
                </p>
                {!order.payment_proof_path ? (
                  <p className="text-xs text-gray-500">No screenshot uploaded yet.</p>
                ) : proofLoading ? (
                  <p className="text-xs text-gray-500">Loading...</p>
                ) : proofUrl ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={proofUrl}
                    alt="Payment screenshot"
                    className="w-full max-h-96 object-contain rounded-xl border border-gray-200 bg-gray-50"
                  />
                ) : (
                  <p className="text-xs text-red-600">Could not load screenshot. Please refresh.</p>
                )}
              </div>
            )}

            {/* Farmer details */}
            {order.farmer && (
              <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
                <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
                  {L('Farmer', 'రైతు')}
                </p>
                <div>
                  <p className="text-base font-extrabold text-gray-900 leading-tight">🧑‍🌾 {order.farmer.name}</p>
                  <p className="text-xs text-gray-500 mt-0.5">📍 {order.farmer.village}</p>
                </div>
                <Link
                  href={`/farmer/${order.farmer.slug}`}
                  className="block text-center text-sm font-bold text-green-700 underline"
                >
                  {L('View farm profile', 'రైతు ప్రొఫైల్ చూడండి ↗')}
                </Link>
                {whatsappHref && (
                  <a
                    href={whatsappHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="w-full bg-green-600 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-700 flex items-center justify-center gap-2"
                  >
                    💬 {L('Contact Farmer', 'రైతును సంప్రదించు')}
                  </a>
                )}
              </div>
            )}

            {/* Report a problem — pins the complaint to this order automatically */}
            <button
              onClick={() => setShowComplaint(true)}
              className="w-full border border-gray-300 text-gray-700 font-bold py-3 rounded-xl text-sm active:bg-gray-50"
            >
              🛟 {L('Report a problem', 'సమస్యను నివేదించండి')}
            </button>
          </>
        )}
      </div>

      {showReceipt && order && (
        <ReceiptOverlay order={order} onClose={() => setShowReceipt(false)} />
      )}

      {showComplaint && order && (
        <ComplaintModal
          presetOrderCode={order.order_code}
          onClose={() => setShowComplaint(false)}
          onCreated={() => setShowComplaint(false)}
        />
      )}
    </main>
  )
}

// Printable payment receipt. Shown as an overlay; the print stylesheet hides
// everything except .yff-receipt so "Print / Save as PDF" produces a clean
// one-page receipt on both phones and laptops.
function ReceiptOverlay({ order, onClose }: { order: Order; onClose: () => void }) {
  const { lang, L } = useLang()
  const placed = new Date(order.created_at).toLocaleString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit',
  })
  const paymentRef = order.razorpay_payment_id || order.order_code || order.id

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4 overflow-y-auto">
      <style>{`@media print {
        body * { visibility: hidden !important; }
        .yff-receipt, .yff-receipt * { visibility: visible !important; }
        .yff-receipt { position: absolute; left: 0; top: 0; width: 100%; box-shadow: none !important; }
        .yff-no-print { display: none !important; }
      }`}</style>

      <div className="yff-receipt bg-white rounded-2xl w-full max-w-sm p-6 my-auto">
        <div className="text-center border-b border-dashed border-gray-300 pb-3">
          <p className="text-lg font-extrabold text-green-700">YourFamilyFarmer</p>
          <p className="text-[11px] text-gray-500">{L('Payment Receipt', 'చెల్లింపు రసీదు')}</p>
        </div>

        <div className="py-3 space-y-1.5 text-xs">
          <div className="flex justify-between"><span className="text-gray-500">{L('Order ID', 'ఆర్డర్ ID')}</span><span className="font-mono font-bold text-gray-900">{order.order_code || order.id.slice(0, 8)}</span></div>
          <div className="flex justify-between"><span className="text-gray-500">{L('Date', 'తేదీ')}</span><span className="font-semibold text-gray-900">{placed}</span></div>
          {order.farmer && (
            <div className="flex justify-between"><span className="text-gray-500">{L('Farmer', 'రైతు')}</span><span className="font-semibold text-gray-900 text-right">{order.farmer.name} · {order.farmer.village}</span></div>
          )}
          <div className="flex justify-between"><span className="text-gray-500">{L('Payment', 'చెల్లింపు')}</span><span className="font-semibold text-gray-900">{order.payment_method_detail || (order.payment_method === 'cod' ? 'Cash on Delivery' : isOnlinePayment(order.payment_method) ? 'UPI' : order.payment_method || '—')}</span></div>
        </div>

        <div className="border-t border-dashed border-gray-300 py-3">
          <div className="flex justify-between text-xs">
            <span className="text-gray-700">{localizeName(order.produce_name, lang)} × {order.quantity} {order.unit || 'kg'}</span>
            <span className="font-semibold text-gray-900">₹{order.total_price ?? 0}</span>
          </div>
        </div>

        <div className="border-t-2 border-gray-900 pt-2 flex justify-between items-center">
          <span className="text-sm font-bold text-gray-900">{L('Total Paid', 'మొత్తం చెల్లించారు')}</span>
          <span className="text-lg font-extrabold text-green-700">₹{order.total_price ?? 0}</span>
        </div>

        <div className="mt-3 text-center">
          <span className="inline-block text-[10px] font-bold px-3 py-1 rounded-full bg-green-100 text-green-800">{L('✓ PAID', 'చెల్లించారు')}</span>
        </div>

        <p className="text-[9px] text-gray-400 text-center mt-3 break-all">Ref: {paymentRef}</p>
        <p className="text-[10px] font-semibold text-green-700 text-center mt-2">{L('Thank you for supporting our farmers — GoGrameen Team 🌱', 'మా రైతులకు మద్దతు ఇచ్చినందుకు ధన్యవాదాలు — గోగ్రామీణ్ టీం')}</p>

        <div className="yff-no-print mt-5 grid grid-cols-2 gap-2">
          <button onClick={onClose} className="border border-gray-300 text-gray-700 font-bold py-2.5 rounded-xl text-sm active:bg-gray-50">{L('Close', 'మూసివేయి')}</button>
          <button onClick={() => window.print()} className="bg-green-700 text-white font-bold py-2.5 rounded-xl text-sm active:bg-green-800">{L('Print', 'ప్రింట్')}</button>
        </div>
      </div>
    </div>
  )
}

function DeliveryPanel({ order }: { order: Order }) {
  const { L } = useLang()
  const ds: DeliveryStatus = (order.delivery_status as DeliveryStatus) || 'unassigned'

  const steps: Array<{ key: DeliveryStatus; label: string; sub: string; at: string | null | undefined }> = [
    { key: 'unassigned', label: 'Order placed', sub: 'Waiting for a delivery boy', at: order.created_at },
    { key: 'assigned', label: 'Rider assigned', sub: 'On the way to farmer', at: order.assigned_at },
    { key: 'picked_up', label: 'Picked up', sub: 'Collected from farmer', at: order.picked_up_at },
    { key: 'out_for_delivery', label: 'Out for delivery', sub: 'On the way to you', at: order.out_for_delivery_at },
    { key: 'delivered', label: 'Delivered', sub: 'Order completed', at: order.delivered_at },
  ]

  const stageIndex = (k: DeliveryStatus) => ['unassigned', 'assigned', 'picked_up', 'out_for_delivery', 'delivered'].indexOf(k)
  const current = stageIndex(ds)

  const formatAt = (iso: string | null | undefined) => {
    if (!iso) return ''
    const d = new Date(iso)
    return d.toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })
  }

  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-4">
      <div className="flex items-center gap-2">
        <span className="text-base">🛵</span>
        <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
          {L('Home delivery', 'ఇంటికి డెలివరీ')}
        </p>
      </div>

      {/* Handover OTP — visible once a rider has been assigned. Customer
          reads this 4-digit code to the rider at the door so the system
          can confirm the right person received the goods. */}
      {ds !== 'unassigned' && ds !== 'delivered' && order.handover_otp && (
        <div className="bg-amber-50 border-2 border-amber-300 rounded-2xl px-4 py-3 text-center">
          <p className="text-[10px] font-bold text-amber-800 uppercase tracking-wide">
            {L('Read this code to the delivery boy at your door', 'డోర్ వద్ద డెలివరీ బాయ్‌కు ఈ కోడ్ చెప్పండి')}
          </p>
          <p className="text-4xl font-black tracking-widest text-amber-900 mt-2 font-mono">
            {order.handover_otp}
          </p>
        </div>
      )}

      {ds === 'delivered' && (
        <div className="bg-green-50 border border-green-200 rounded-2xl px-4 py-3 text-center">
          <p className="text-sm font-extrabold text-green-800">✓ Delivered</p>
          <p className="text-xs text-green-700 mt-0.5">{formatAt(order.delivered_at)}</p>
        </div>
      )}

      {/* Status timeline */}
      <ol className="space-y-2">
        {steps.map((s, idx) => {
          const reached = idx <= current
          const isCurrent = idx === current
          return (
            <li key={s.key} className="flex items-start gap-3">
              <div className="flex flex-col items-center pt-0.5">
                <span className={`w-3 h-3 rounded-full ${reached ? 'bg-green-700' : 'bg-gray-200'} ${isCurrent ? 'ring-2 ring-green-200' : ''}`} />
                {idx < steps.length - 1 && (
                  <span className={`w-0.5 flex-1 mt-0.5 ${idx < current ? 'bg-green-700' : 'bg-gray-200'}`} style={{ minHeight: 14 }} />
                )}
              </div>
              <div className="flex-1 pb-1">
                <p className={`text-xs font-bold ${reached ? 'text-gray-900' : 'text-gray-400'}`}>{s.label}</p>
                <p className="text-[10px] text-gray-500 leading-snug">{s.sub}</p>
                {s.at && reached && (
                  <p className="text-[10px] text-gray-400 mt-0.5">{formatAt(s.at)}</p>
                )}
              </div>
            </li>
          )
        })}
      </ol>

      {/* Delivery address (always visible — confirms what consumer entered) */}
      {order.delivery_address && (
        <div className="border-t border-gray-100 pt-3">
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide mb-1">Delivering to</p>
          <p className="text-xs text-gray-800 leading-snug whitespace-pre-line">{order.delivery_address}</p>
          {order.delivery_landmark && (
            <p className="text-xs text-gray-600 mt-0.5">📍 {order.delivery_landmark}</p>
          )}
          {order.delivery_pincode && (
            <p className="text-xs text-gray-600">PIN: {order.delivery_pincode}</p>
          )}
        </div>
      )}

      {/* Rider contact — only when assigned (and not yet delivered) */}
      {order.rider && ds !== 'delivered' && (
        <div className="border-t border-gray-100 pt-3">
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">{L('Delivery boy', 'డెలివరీ బాయ్')}</p>
          <p className="text-sm font-bold text-gray-900 mt-1">{order.rider.name || 'Your delivery partner'}</p>
          <a
            href={`tel:${order.rider.phone}`}
            className="mt-2 w-full inline-flex items-center justify-center gap-2 bg-blue-600 text-white font-bold py-3 rounded-xl text-sm active:bg-blue-700"
          >
            📞 Call · {order.rider.phone}
          </a>
        </div>
      )}
    </div>
  )
}

// Order status timeline for self-pickup and courier orders. Home delivery has
// its own richer DeliveryPanel; this covers the pickup and courier lifecycles.
// Courier diverges after "Confirmed": Shipped → Received instead of Ready →
// Picked up, so a courier buyer sees the right milestones (and dates).
function OrderStatusPanel({ order }: { order: Order }) {
  const { L } = useLang()
  const approved = order.status === 'approved'
  // Shipped lifecycle (Shipped → Received) covers courier AND farmer-shipped
  // home deliveries. Rider home deliveries never reach this panel. Self-pickup
  // keeps the Ready → Picked up lifecycle.
  const isShippedFlow = order.delivery_type === 'courier' || order.delivery_type === 'home_delivery'
  const isCourier = isShippedFlow
  const collected = !!order.collected_at
  const shipped = !!order.shipped_at
  const received = !!order.received_at
  // Online orders that have been paid show an extra "Payment received" step.
  const paidOnline = isOnlinePayment(order.payment_method)
    && (order.payment_status === 'paid' || order.payment_status === 'completed')

  const fmt = (iso?: string | null) =>
    iso ? new Date(iso).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''

  type Step = { label: string; sub: string; at: string; done: boolean }
  const steps: Step[] = [
    { label: L('Order placed', 'ఆర్డర్ పెట్టారు'), sub: L('We received your order', 'మీ ఆర్డర్ అందింది'), at: fmt(order.created_at), done: true },
    ...(paidOnline
      ? [{ label: L('Payment received', 'చెల్లింపు అందింది'), sub: `${order.payment_method_detail || 'UPI'} payment confirmed / చెల్లింపు ధృవీకరించబడింది`, at: fmt(order.paid_at), done: true }]
      : []),
    { label: L('Confirmed by farmer', 'రైతు ధృవీకరించారు'), sub: L('Farmer accepted your order', 'రైతు అంగీకరించారు'), at: fmt(order.confirmed_at), done: approved },
    ...(isCourier
      ? [
          { label: L('Shipped', 'షిప్ చేయబడింది'), sub: L('Farmer shipped your order to your address', 'రైతు మీ చిరునామాకు పంపారు'), at: fmt(order.shipped_at), done: shipped },
          { label: L('Received', 'అందుకున్నారు'), sub: L('You confirmed you received it', 'మీరు అందుకున్నట్టు ధృవీకరించారు'), at: fmt(order.received_at), done: received },
        ]
      : [
          { label: L('Ready for pickup', 'తీసుకెళ్లడానికి సిద్ధం'), sub: order.pickup_location ? `Collect at ${order.pickup_location}` : L('Collect from the farmer', 'రైతు నుండి తీసుకోండి'), at: '', done: approved },
          { label: L('Picked up', 'తీసుకున్నారు'), sub: L('Collection confirmed', 'తీసుకున్నట్టు ధృవీకరించారు'), at: fmt(order.collected_at), done: collected },
        ]),
  ]

  // Current = the furthest milestone reached (last step marked done).
  let current = 0
  steps.forEach((s, i) => { if (s.done) current = i })

  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-4">
      {/* Header — mirrors the home-delivery panel so every order type's tracker
          looks the same, just with the icon/label for this fulfilment type. */}
      <div className="flex items-center gap-2">
        <span className="text-base">{order.delivery_type === 'home_delivery' ? '🛵' : isShippedFlow ? '📦' : '🧺'}</span>
        <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
          {order.delivery_type === 'home_delivery'
            ? L('Home delivery', 'ఇంటి డెలివరీ')
            : isShippedFlow ? L('Courier delivery', 'కొరియర్ డెలివరీ') : L('Farm pickup', 'ఫామ్ పికప్')}
        </p>
      </div>

      {/* Prominent completion banner once the order is resolved — same style as
          the "Delivered" banner on the home-delivery tracker. */}
      {(received || collected) && (
        <div className="bg-green-50 border border-green-200 rounded-2xl px-4 py-3 text-center">
          <p className="text-sm font-extrabold text-green-800">
            {isCourier ? `✓ ${L('Received', 'అందుకున్నారు')}` : `✓ ${L('Picked up', 'తీసుకున్నారు')}`}
          </p>
          <p className="text-xs text-green-700 mt-0.5">{fmt(isCourier ? order.received_at : order.collected_at)}</p>
        </div>
      )}

      {/* Handover code — shown once the order is ready and before it's
          collected. The customer reads it to the farmer at pickup. */}
      {approved && !collected && order.handover_otp && (
        <div className="bg-amber-50 border-2 border-amber-300 rounded-2xl px-4 py-3 text-center">
          <p className="text-[10px] font-bold text-amber-800 uppercase tracking-wide">
            {L('Show this code to the farmer when you collect', 'తీసుకునేటప్పుడు ఈ కోడ్ రైతుకు చెప్పండి')}
          </p>
          <p className="text-4xl font-black tracking-widest text-amber-900 mt-2 font-mono">
            {order.handover_otp}
          </p>
        </div>
      )}

      <ol className="space-y-2">
        {steps.map((s, idx) => {
          const reached = idx <= current
          const isCurrent = idx === current
          return (
            <li key={s.label} className="flex items-start gap-3">
              <div className="flex flex-col items-center pt-0.5">
                <span className={`w-3 h-3 rounded-full ${reached ? 'bg-green-700' : 'bg-gray-200'} ${isCurrent ? 'ring-2 ring-green-200' : ''}`} />
                {idx < steps.length - 1 && (
                  <span className={`w-0.5 mt-0.5 ${idx < current ? 'bg-green-700' : 'bg-gray-200'}`} style={{ minHeight: 14 }} />
                )}
              </div>
              <div className="flex-1 pb-1">
                <p className={`text-xs font-bold ${reached ? 'text-gray-900' : 'text-gray-400'}`}>{s.label}</p>
                <p className="text-[10px] text-gray-500 leading-snug">{s.sub}</p>
                {s.at && reached && <p className="text-[10px] text-gray-400 mt-0.5">{s.at}</p>}
              </div>
            </li>
          )
        })}
      </ol>
    </div>
  )
}

// Refund timeline. Maps the stored refund_status (our manual 'initiated', or
// a Razorpay status: 'pending' / 'processed' / 'failed') onto a simple
// buyer-facing progression: Initiated → Processing → Credited.
function RefundPanel({ order }: { order: Order }) {
  const { L } = useLang()
  const rs = (order.refund_status || '').toLowerCase()
  const failed = rs === 'failed'
  const amount = order.refund_amount ?? order.total_price ?? 0

  // current = how far along the 3-step bar we are.
  // initiated → 0, pending → 1, processed → 2 (credited).
  const current = rs === 'processed' ? 2 : rs === 'pending' ? 1 : 0

  const steps = [
    { label: L('Refund initiated', 'రీఫండ్ మొదలైంది'), sub: L('We started your refund', 'మీ రీఫండ్ ప్రారంభించాం') },
    { label: L('Processing', 'ప్రాసెస్ అవుతోంది'), sub: L('Sent to your bank/UPI', 'మీ బ్యాంక్/UPIకి పంపాం') },
    { label: L('Credited', 'జమ అయింది'), sub: L('Reflects in 3–5 business days', '3–5 పని రోజుల్లో కనిపిస్తుంది') },
  ]

  const refundedAt = order.refunded_at
    ? new Date(order.refunded_at).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })
    : null

  if (failed) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-2xl p-4 space-y-1.5">
        <span className="inline-block text-[10px] font-bold px-2 py-0.5 rounded-full bg-red-100 text-red-800">
          {L('⚠️ Refund failed', 'రీఫండ్ విఫలమైంది')}
        </span>
        <p className="text-sm text-red-800 leading-snug">
          {L(`Your refund of ₹${amount} could not be processed. Please contact support and we'll fix it.`, `మీ ₹${amount} రీఫండ్ ప్రాసెస్ కాలేదు. దయచేసి సపోర్ట్‌ను సంప్రదించండి, మేము సరి చేస్తాం.`)}
        </p>
      </div>
    )
  }

  return (
    <div className="bg-purple-50 border border-purple-200 rounded-2xl p-4 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <span className="inline-block text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-100 text-purple-800">
          💸 Refund of ₹{amount}
        </span>
        {refundedAt && <span className="text-[10px] text-purple-500">{refundedAt}</span>}
      </div>

      <ol className="space-y-2">
        {steps.map((s, idx) => {
          const reached = idx <= current
          const isCurrent = idx === current
          return (
            <li key={s.label} className="flex items-start gap-3">
              <div className="flex flex-col items-center pt-0.5">
                <span className={`w-3 h-3 rounded-full ${reached ? 'bg-purple-600' : 'bg-purple-200'} ${isCurrent ? 'ring-2 ring-purple-200' : ''}`} />
                {idx < steps.length - 1 && (
                  <span className={`w-0.5 mt-0.5 ${idx < current ? 'bg-purple-600' : 'bg-purple-200'}`} style={{ minHeight: 14 }} />
                )}
              </div>
              <div className="flex-1 pb-1">
                <p className={`text-xs font-bold ${reached ? 'text-purple-900' : 'text-purple-300'}`}>{s.label}</p>
                <p className="text-[10px] text-purple-500 leading-snug">{s.sub}</p>
              </div>
            </li>
          )
        })}
      </ol>

      {order.refund_id && (
        <p className="text-[10px] text-purple-400 font-mono border-t border-purple-100 pt-2">Ref: {order.refund_id}</p>
      )}
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const CANCEL_WINDOW_MS = 30 * 60 * 1000 // 30 minutes

// Buyer cancels their own order. Allowed only while it is still pending (the
// farmer hasn't confirmed) AND within 30 minutes of placing it. Returns the
// stock and, for a paid order, issues a real Razorpay refund — same machinery
// as a farmer decline, but initiated by the buyer.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, consumer_id, status, quantity, total_price, produce_listing_id, payment_status, razorpay_payment_id, created_at, order_code')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (order.status !== 'pending') {
    return NextResponse.json(
      { error: 'This order can no longer be cancelled — the farmer has already responded.' },
      { status: 409 },
    )
  }
  const placedMs = order.created_at ? new Date(order.created_at).getTime() : 0
  if (!placedMs || Date.now() - placedMs > CANCEL_WINDOW_MS) {
    return NextResponse.json(
      { error: 'The 30-minute cancellation window has passed. Please contact the farmer.' },
      { status: 409 },
    )
  }

  // Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on cancel failed:', e)
    }
  }

  const update: Record<string, unknown> = { status: 'cancelled', decline_reason: 'Cancelled by buyer' }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id, reason: 'buyer_cancel' },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        console.error('[YFF] razorpay refund on cancel failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not cancelled — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] cancel update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not cancel the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, refunded: !!update.refund_id })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ orders: [] }, { status: 200 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: orders, error } = await supabase
    .from('orders')
    .select(
      'id, order_code, produce_name, produce_listing_id, quantity, unit, total_price, pickup_location, status, payment_method, payment_status, refund_status, refund_id, refund_amount, refunded_at, decline_reason, payment_proof_path, created_at, farmer_id, delivery_type, delivery_status, delivery_address, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, handover_otp, assigned_at, picked_up_at, out_for_delivery_at, delivered_at, shipped_at, collected_at, received_at',
    )
    .eq('consumer_id', session.consumerId)
    .order('created_at', { ascending: false })
    .limit(100)

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Manual join — orders.farmer_id has no FK constraint, so PostgREST can't
  // embed the farmer resource for us. One extra query keeps it simple.
  const farmerIds = [...new Set((orders ?? []).map((o) => o.farmer_id).filter(Boolean))]
  let farmerMap: Record<string, { name: string; slug: string; village: string; phone: string | null; upi_id: string | null }> = {}
  if (farmerIds.length > 0) {
    const { data: farmers } = await supabase
      .from('farmers')
      .select('id, name, slug, village, phone, upi_id')
      .in('id', farmerIds)
    farmerMap = Object.fromEntries(
      (farmers ?? []).map((f) => [
        f.id,
        { name: f.name, slug: f.slug, village: f.village, phone: f.phone ?? null, upi_id: (f.upi_id as string | null) ?? null },
      ]),
    )
  }

  // Pull rider contact for any order that's been assigned. Only ever expose
  // the rider's name + phone — never id-proof or password fields.
  const riderIds = [...new Set(
    (orders ?? [])
      .map((o) => (o as { delivery_boy_id?: string | null }).delivery_boy_id)
      .filter((v): v is string => !!v),
  )]
  let riderMap: Record<string, { id: string; name: string | null; phone: string }> = {}
  if (riderIds.length > 0) {
    const { data: riders } = await supabase
      .from('delivery_boys')
      .select('id, name, phone')
      .in('id', riderIds)
    riderMap = Object.fromEntries(
      (riders ?? []).map((r) => [r.id, { id: r.id, name: r.name ?? null, phone: r.phone }]),
    )
  }

  // The buyer's own produce feedback per order, so each card can show "Give
  // feedback" vs the rating they already left. Guarded: if the produce_reviews
  // table hasn't been created yet (migration not run), we just skip it rather
  // than fail the whole orders list.
  const orderIds = (orders ?? []).map((o) => o.id)
  let reviewMap: Record<string, { id: string; star_rating: number; review_text: string | null; created_at: string }> = {}
  if (orderIds.length > 0) {
    const { data: reviews } = await supabase
      .from('produce_reviews')
      .select('id, order_id, star_rating, review_text, created_at')
      .in('order_id', orderIds)
    if (reviews) {
      reviewMap = Object.fromEntries(
        reviews.map((r) => [
          r.order_id,
          { id: r.id, star_rating: r.star_rating, review_text: r.review_text ?? null, created_at: r.created_at },
        ]),
      )
    }
  }

  const enriched = (orders ?? []).map((o) => {
    const riderId = (o as { delivery_boy_id?: string | null }).delivery_boy_id ?? null
    return {
      ...o,
      farmer: farmerMap[o.farmer_id] ?? null,
      rider: riderId ? riderMap[riderId] ?? null : null,
      my_review: reviewMap[o.id] ?? null,
    }
  })
  return NextResponse.json({ orders: enriched })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer declines a pending order. This runs server-side (not in the
// dashboard) because issuing a real refund needs the Razorpay secret. Steps:
//   1. authorise the farmer and confirm the order is theirs and still pending
//   2. return the reserved stock
//   3. if the buyer paid by Razorpay, issue a real partial refund for this
//      line's amount and record it; other paid methods get a manual
//      'initiated' marker as before
//   4. mark the order declined
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, quantity, total_price, produce_listing_id, payment_method, payment_status, razorpay_payment_id, order_code')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // Only a pending order can be declined. This also makes the call idempotent:
  // a double-tap finds the order already declined and refunds nothing twice.
  if (order.status !== 'pending') {
    return NextResponse.json({ error: 'This order can no longer be declined.' }, { status: 409 })
  }

  // 1. Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on decline failed:', e)
    }
  }

  // 2. Refund if the buyer actually paid.
  const update: Record<string, unknown> = { status: 'declined', decline_reason: reason || null }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        // Refund failed at Razorpay. Don't silently swallow it — keep the
        // order pending so the farmer can retry, and surface the error.
        console.error('[YFF] razorpay refund failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not declined — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    // Non-Razorpay paid (UPI/manual): flag for manual refund as before.
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] decline update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not decline the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({
    ok: true,
    refunded: !!update.refund_id,
    refundStatus: (update.refund_status as string | undefined) ?? null,
  })
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import LanguageToggle from '@/components/LanguageToggle'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ComplaintModal from '@/components/consumer/ComplaintModal'
import OrderFeedbackModal from '@/components/consumer/OrderFeedbackModal'
import OrderCard, { ConsumerOrder as Order, isResolved, isCompleted } from '@/components/consumer/OrderCard'

export default function ConsumerOrderHistoryPage() {
  const { tx, L } = useLang()
  const { state, openAuth } = useConsumerAuth()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  // Order code the complaint modal is pinned to ('' means a general complaint
  // with no preset). null means the modal is closed.
  const [complaintFor, setComplaintFor] = useState<string | null>(null)
  // Order the feedback sheet is open for (null = closed).
  const [feedbackFor, setFeedbackFor] = useState<Order | null>(null)

  const refresh = useCallback(async () => {
    setLoading(true)
    setError('')
    const r = await fetch('/api/consumer/orders', { credentials: 'same-origin' }).catch(() => null)
    if (!r) { setError('Could not load orders. Check your connection.'); setLoading(false); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load orders.'); setLoading(false); return }
    setOrders((json.orders ?? []) as Order[])
    setLoading(false)
  }, [])

  useEffect(() => {
    if (state.status === 'authenticated') {
      void refresh()
    } else if (state.status === 'anonymous') {
      setLoading(false)
    }
  }, [state.status, refresh])

  // Resolved orders only — delivered / picked up / received / declined /
  // cancelled. Active ones stay on /consumer/orders.
  const completedOrders = orders.filter(isResolved)
  const activeCount = orders.length - completedOrders.length

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <div className="flex items-center justify-between mb-4">
          <Link href="/consumer/orders" className="text-green-300 text-sm flex items-center gap-1">
            {L('← Back to orders', '← ఆర్డర్‌లకు తిరిగి')}
          </Link>
          <LanguageToggle />
        </div>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {L('Order history', 'ఆర్డర్ చరిత్ర')}
        </h1>
        <p className="text-green-400 text-sm mt-1">
          {L('Completed, picked up & cancelled orders', 'పూర్తయిన, తీసుకున్న & రద్దు చేసిన ఆర్డర్‌లు')}
        </p>
      </div>

      <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
        {/* Active | History switcher — mirrors the active orders page. */}
        {state.status === 'authenticated' && !error && (
          <div className="bg-white rounded-2xl border border-gray-100 p-1.5 flex gap-1.5">
            <Link
              href="/consumer/orders"
              className="flex-1 py-2.5 rounded-xl text-xs font-bold text-center bg-gray-50 text-gray-600 active:bg-gray-100"
            >
              {L('Active', 'ప్రస్తుత')}{activeCount > 0 ? ` (${activeCount})` : ''}
            </Link>
            <span className="flex-1 py-2.5 rounded-xl text-xs font-bold text-center bg-green-700 text-white">
              {L('History', 'చరిత్ర')} ({completedOrders.length})
            </span>
          </div>
        )}

        {state.status === 'loading' || loading ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center text-sm text-gray-500">
            {L('Loading...', 'లోడ్ అవుతోంది')}
          </div>
        ) : state.status === 'anonymous' ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-4">
            <div className="text-5xl">🔒</div>
            <div>
              <p className="font-bold text-gray-900">
                {L('Log in to see your orders', 'మీ ఆర్డర్‌లు చూడటానికి లాగిన్ అవ్వండి')}
              </p>
            </div>
            <button
              onClick={openAuth}
              className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
            >
              {L('Log in', 'లాగిన్')}
            </button>
          </div>
        ) : error ? (
          <div className="bg-white rounded-2xl border border-red-100 p-6 space-y-3">
            <p className="text-sm text-red-600">{error}</p>
            <button
              onClick={() => void refresh()}
              className="text-sm font-bold text-green-700 underline"
            >
              {L('Try again', 'మళ్లీ ప్రయత్నించండి')}
            </button>
          </div>
        ) : completedOrders.length === 0 ? (
          <div className="text-center py-14">
            <div className="text-5xl mb-3">📦</div>
            <p className="font-semibold text-gray-500 text-sm">
              {L('No completed orders yet', 'పూర్తయిన ఆర్డర్‌లు లేవు')}
            </p>
            <Link href="/consumer/orders" className="mt-4 inline-block text-green-700 text-sm underline font-semibold">
              {L('← Active orders', '← ప్రస్తుత ఆర్డర్‌లు')}
            </Link>
          </div>
        ) : (
          <div className="space-y-3">
            {completedOrders.map((order) => (
              <OrderCard key={order.id} order={order} onComplaint={setComplaintFor} onFeedback={setFeedbackFor} />
            ))}
          </div>
        )}
      </div>

      {complaintFor !== null && (
        <ComplaintModal
          presetOrderCode={complaintFor || null}
          onClose={() => setComplaintFor(null)}
          onCreated={() => setComplaintFor(null)}
        />
      )}

      {feedbackFor && (
        <OrderFeedbackModal
          orderId={feedbackFor.id}
          produceName={feedbackFor.produce_name}
          completed={isCompleted(feedbackFor)}
          existing={feedbackFor.my_review ?? null}
          onClose={() => setFeedbackFor(null)}
          onSaved={() => { setFeedbackFor(null); void refresh() }}
        />
      )}
    </main>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Buyer confirms they received a shipped courier order. Only allowed once the
// farmer has marked it shipped (shipped_at set). Stamps received_at, which
// resolves the order and moves it to history on both sides.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, consumer_id, status, delivery_type, shipped_at, received_at')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (order.delivery_type !== 'courier') {
    return NextResponse.json({ error: 'Only a courier order is confirmed this way.' }, { status: 409 })
  }
  if (!order.shipped_at) {
    return NextResponse.json({ error: 'This order has not been shipped yet.' }, { status: 409 })
  }
  if (order.received_at) {
    return NextResponse.json({ error: 'This order is already marked received.' }, { status: 409 })
  }

  const { data: updated, error: updErr } = await supabase
    .from('orders')
    .update({ received_at: new Date().toISOString() })
    .eq('id', id)
    .eq('consumer_id', session.consumerId)
    .not('shipped_at', 'is', null)
    .is('received_at', null)
    .select('id, received_at')

  if (updErr) {
    console.error('[YFF consumer/received] update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not confirm receipt. Please try again.' }, { status: 500 })
  }
  if (!updated || updated.length === 0) {
    return NextResponse.json({ error: 'Could not confirm receipt. Refresh and try again.' }, { status: 409 })
  }

  return NextResponse.json({ ok: true, received_at: updated[0].received_at })
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'

type Order = {
  id: string
  farmer_id: string
  order_code: string | null
  produce_listing_id: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined'
  payment_status: string | null
  decline_reason: string | null
  refund_status: string | null
  refund_amount: number | null
  refunded_at: string | null
  delivery_type: 'self_pickup' | 'home_delivery' | 'courier' | null
  collected_at: string | null
  shipped_at: string | null
  received_at: string | null
  fulfillment_date: string | null
  created_at: string
}

type Filter = 'today' | 'week' | 'month'

export default function OrderHistoryPage() {
  const router = useRouter()
  const { tx, L } = useLang()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<Filter>('week')

  const load = useCallback(async () => {
    const farmerId = localStorage.getItem('yff_farmer_id')
    if (!farmerId) { router.replace('/farmer/login'); return }

    setLoading(true)
    // Explicit columns: handover_otp is deliberately NOT fetched — the pickup
    // code must come from the customer, so the farmer's browser never sees it.
    const { data } = await supabase
      .from('orders')
      .select('id, farmer_id, order_code, produce_listing_id, produce_name, quantity, unit, total_price, buyer_name, buyer_phone, pickup_location, status, payment_status, decline_reason, refund_status, refund_amount, refunded_at, delivery_type, collected_at, shipped_at, received_at, fulfillment_date, created_at')
      .eq('farmer_id', farmerId)
      .in('status', ['approved', 'declined'])
      .order('created_at', { ascending: false })

    setOrders((data ?? []) as Order[])
    setLoading(false)
  }, [router])

  useEffect(() => { load() }, [load])

  // Farmer sets/updates the pickup-or-delivery date on an approved order.
  const setFulfillmentDate = async (orderId: string, date: string) => {
    const value = date || null
    setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, fulfillment_date: value } : o)))
    await supabase.from('orders').update({ fulfillment_date: value }).eq('id', orderId)
  }

  const filterStart = () => {
    if (filter === 'today') {
      const d = new Date()
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    }
    if (filter === 'week') return Date.now() - 7 * 86400000
    return Date.now() - 30 * 86400000
  }

  const filtered = orders.filter((o) => new Date(o.created_at).getTime() >= filterStart())
  const revenue = filtered
    .filter((o) => o.status === 'approved')
    .reduce((sum, o) => sum + (o.total_price ?? 0), 0)

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <Link href="/farmer/dashboard" className="text-green-300 text-sm flex items-center gap-1 mb-4">
          ← {tx.back}
        </Link>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {tx.orderHistory}
        </h1>
        <p className="text-green-400 text-sm mt-1">Approved &amp; declined orders</p>
      </div>

      <div className="px-4 -mt-5 space-y-4">
        {/* Filter pills */}
        <div className="bg-white rounded-2xl border border-gray-100 p-3 flex gap-2">
          {(['today', 'week', 'month'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-colors ${
                filter === f ? 'bg-green-700 text-white' : 'bg-gray-100 text-gray-600 active:bg-gray-200'
              }`}
            >
              {f === 'today' ? tx.filterToday : f === 'week' ? tx.filterWeek : tx.filterMonth}
            </button>
          ))}
        </div>

        {/* Revenue summary */}
        {revenue > 0 && (
          <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-green-700 uppercase tracking-wide">
                {tx.totalRevenue}
              </p>
              <p className="text-3xl font-black text-green-800 mt-0.5">₹{revenue}</p>
            </div>
            <div className="text-4xl">💰</div>
          </div>
        )}

        {/* Order list */}
        {loading ? (
          <div className="text-center py-16">
            <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
            <p className="text-gray-500 text-sm mt-3">{tx.loadingLabel}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noPendingOrders}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map((order) => (
              <HistoryCard
                key={order.id}
                order={order}
                onSetDate={(d) => setFulfillmentDate(order.id, d)}
              />
            ))}
          </div>
        )}
      </div>
    </main>
  )
}

function HistoryCard({ order, onSetDate }: { order: Order; onSetDate: (date: string) => void }) {
  const { tx, L } = useLang()
  const isApproved = order.status === 'approved'
  const isDelivery = order.delivery_type === 'home_delivery'
  const isCourier = order.delivery_type === 'courier'

  const timeStr = new Date(order.created_at).toLocaleDateString('en-IN', {
    day: 'numeric',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
  })

  const stamp = (iso: string | null) =>
    iso ? new Date(iso).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''

  // Completion line for an approved order: the final milestone + its date.
  // Shipped flow (courier + farmer-shipped home delivery): Received (done) ▸
  // Shipped (in transit). Pickup: Picked up.
  const isShippedFlow = isCourier || isDelivery
  const completion = !isApproved ? null
    : isShippedFlow
      ? order.received_at
        ? { text: `${L('✓ Received', '✓ అందుకున్నారు')} · ${stamp(order.received_at)}`, cls: 'text-green-700' }
        : order.shipped_at
          ? { text: `${L('🚚 Shipped', '🚚 షిప్ చేయబడింది')} · ${stamp(order.shipped_at)}`, cls: 'text-amber-700' }
          : null
      : order.collected_at
        ? { text: `${L('✓ Picked up', '✓ తీసుకువెళ్ళారు')} · ${stamp(order.collected_at)}`, cls: 'text-green-700' }
        : null

  return (
    <div className={`rounded-2xl border overflow-hidden ${isApproved ? 'border-green-200 bg-white' : 'border-gray-200 bg-gray-50'}`}>
      <div className="p-3 space-y-1.5">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {order.buyer_name || '—'}
              </p>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                isApproved ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-700'
              }`}>
                {isApproved ? tx.statusApproved : tx.statusDeclined}
              </span>
            </div>
            {order.buyer_phone && (
              <a href={`tel:+91${order.buyer_phone}`} className="text-xs font-semibold text-green-700">
                📞 +91 {order.buyer_phone}
              </a>
            )}
          </div>
          <div className="flex flex-col items-end flex-shrink-0 mt-0.5">
            <span className="text-[11px] text-gray-400 whitespace-nowrap">
              {timeStr}
            </span>
            {order.order_code && (
              <span className="text-[10px] font-mono font-semibold text-gray-400 whitespace-nowrap">
                {order.order_code}
              </span>
            )}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-1.5 text-sm">
          <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
          <span className="text-gray-300">·</span>
          <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
          {order.total_price != null && order.total_price > 0 && (
            <>
              <span className="text-gray-300">·</span>
              <span className="font-bold text-green-700">₹{order.total_price}</span>
            </>
          )}
        </div>

        {order.pickup_location && (
          <p className="text-xs text-gray-500">📍 {order.pickup_location}</p>
        )}

        {/* Completion status + date (picked up / shipped / received). */}
        {completion && (
          <p className={`text-xs font-bold ${completion.cls}`}>{completion.text}</p>
        )}

        {/* Approved orders: farmer sets/edits the pickup-or-delivery date. */}
        {isApproved && (
          <div className="pt-1">
            <label className="text-[11px] font-bold text-gray-600 block mb-1">
              📅 {isDelivery ? tx.deliveryDateLabel : tx.pickupDateLabel}
            </label>
            <input
              type="date"
              value={order.fulfillment_date ?? ''}
              onChange={(e) => onSetDate(e.target.value)}
              className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm bg-white focus:border-green-500 focus:outline-none"
            />
          </div>
        )}

        {/* Declined orders: show the reason and the refund status to the farmer */}
        {!isApproved && order.decline_reason && (
          <p className="text-xs text-gray-600 leading-snug">
            <span className="font-semibold">{L('Reason', 'కారణం:')}</span> {order.decline_reason}
          </p>
        )}
        {!isApproved && (order.refund_status || (order.refund_amount ?? 0) > 0) && (
          <div className="mt-1 bg-green-50 border border-green-200 rounded-lg px-2.5 py-1.5">
            <p className="text-xs font-bold text-green-800 flex items-center gap-1">
              {L('💸 Refund initiated to customer', 'రీఫండ్ ప్రారంభమైంది')}
            </p>
            <p className="text-[11px] text-gray-600 leading-snug mt-0.5">
              ₹{order.refund_amount ?? order.total_price ?? 0} · reflects in 3–5 business days
              {order.refunded_at && (
                <> · {new Date(order.refunded_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</>
              )}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

function TodayScheduleSection({ farmerId }: { farmerId: string }) {
  const { tx, L } = useLang()
  const todayStr = new Date().toLocaleDateString('en-CA') // YYYY-MM-DD, local
  const [date, setDate] = useState(todayStr)
  const [orders, setOrders] = useState<ScheduleOrder[]>([])
  const [loading, setLoading] = useState(true)
  const [busyId, setBusyId] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    supabase
      .from('orders')
      .select('id, buyer_name, buyer_phone, produce_name, quantity, unit, pickup_location, delivery_type, delivery_status, shipped_at, collected_at, received_at, created_at')
      .eq('farmer_id', farmerId)
      .eq('status', 'approved')
      .eq('fulfillment_date', date)
      .order('created_at', { ascending: true })
      .then(({ data }) => {
        if (cancelled) return
        setOrders((data ?? []) as ScheduleOrder[])
        setLoading(false)
      })
    return () => { cancelled = true }
  }, [farmerId, date])

  // Self-pickup: stamp collected_at (resolves the order). We keep the row in the
  // schedule but flip it to a "Picked up" done-state so the farmer sees it's
  // closed for the day. Uses the same API route as the orders list.
  const markPickedUp = async (orderId: string) => {
    setBusyId(orderId)
    const res = await fetch(`/api/farmer/orders/${orderId}/picked-up`, { method: 'POST', credentials: 'same-origin' })
    if (res.ok) {
      setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, collected_at: new Date().toISOString() } : o)))
    }
    setBusyId(null)
  }

  // Courier / farmer-shipped home delivery: stamp shipped_at (order stays open
  // until it's confirmed received). Same API route as the orders list.
  const markShipped = async (orderId: string) => {
    setBusyId(orderId)
    const res = await fetch(`/api/farmer/orders/${orderId}/ship`, { method: 'POST', credentials: 'same-origin' })
    if (res.ok) {
      const json = (await res.json().catch(() => ({}))) as { shipped_at?: string }
      const shippedAt = json.shipped_at ?? new Date().toISOString()
      setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, shipped_at: shippedAt } : o)))
    }
    setBusyId(null)
  }

  // Farmer closes a shipped order himself (self-delivered/handed over). Stamps
  // received_at, which resolves the order so it drops from the schedule.
  const markDelivered = async (orderId: string) => {
    setBusyId(orderId)
    const res = await fetch(`/api/farmer/orders/${orderId}/delivered`, { method: 'POST', credentials: 'same-origin' })
    if (res.ok) {
      setOrders((prev) => prev.map((o) => (o.id === orderId ? { ...o, received_at: new Date().toISOString() } : o)))
    }
    setBusyId(null)
  }

  // Today's Schedule shows only active orders — drop anything resolved (picked
  // up / received / delivered) so a finished pickup disappears once it's done.
  const active = orders.filter((o) => !isScheduleResolved(o))
  const pickups = active.filter((o) => o.delivery_type !== 'home_delivery')
  const deliveries = active.filter((o) => o.delivery_type === 'home_delivery')

  const Row = ({ o }: { o: ScheduleOrder }) => {
    const isCourier = o.delivery_type === 'courier'
    const isHomeDelivery = o.delivery_type === 'home_delivery'
    const isPickup = !isCourier && !isHomeDelivery // self_pickup (or legacy null)
    // Home delivery with a rider assigned is closed by the rider; with no rider
    // it's farmer-shipped. Courier and farmer-shipped home delivery both use the
    // "Shipped" action.
    const riderAssigned = isHomeDelivery
      && o.delivery_status != null
      && o.delivery_status !== 'unassigned'
    const shipFlow = isCourier || (isHomeDelivery && !riderAssigned)
    const busy = busyId === o.id
    return (
      <div className="border border-gray-100 rounded-xl px-3 py-2.5 bg-gray-50 space-y-2">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <p className="text-sm font-bold text-gray-900 truncate">{o.produce_name} · {o.quantity} {o.unit || 'kg'}</p>
            <p className="text-xs text-gray-600 truncate">🧑 {o.buyer_name || L('Buyer', 'కొనుగోలుదారు')}</p>
            {o.pickup_location && <p className="text-[11px] text-gray-500 truncate">📍 {o.pickup_location}</p>}
          </div>
          {o.buyer_phone && (
            <a href={`tel:+91${o.buyer_phone}`} className="text-[11px] font-bold text-green-700 bg-green-50 border border-green-200 rounded-lg px-2.5 py-1.5 whitespace-nowrap">
              📞 {o.buyer_phone}
            </a>
          )}
        </div>

        {/* Action: courier & farmer-shipped home delivery → Shipped; self-pickup
            → Picked Up. Rider home-deliveries are closed by the rider, so they
            carry no button here. Once acted on, the row shows a done badge. */}
        {shipFlow && (o.shipped_at ? (
          // Already shipped — farmer can close it out himself once handed over,
          // which stamps received_at and drops the row from the schedule.
          <div className="space-y-1.5">
            <p className="text-xs font-bold text-amber-700">🚚 {L('Shipped', 'షిప్ చేయబడింది')}</p>
            <button
              onClick={() => markDelivered(o.id)}
              disabled={busy}
              className="w-full bg-green-600 text-white font-bold py-2 rounded-lg text-xs active:bg-green-700 disabled:opacity-50"
            >
              {busy ? '…' : `✓ ${L('Delivered', 'డెలివరీ అయింది')}`}
            </button>
          </div>
        ) : (
          <button
            onClick={() => markShipped(o.id)}
            disabled={busy}
            className="w-full bg-amber-600 text-white font-bold py-2 rounded-lg text-xs active:bg-amber-700 disabled:opacity-50"
          >
            {busy ? '…' : `🚚 ${L('Shipped', 'షిప్ చేయబడింది')}`}
          </button>
        ))}
        {/* Self-pickup: only ever the "Picked Up" action. Tapping it resolves
            the order, which drops the row from the schedule. */}
        {isPickup && (
          <button
            onClick={() => markPickedUp(o.id)}
            disabled={busy}
            className="w-full bg-green-600 text-white font-bold py-2 rounded-lg text-xs active:bg-green-700 disabled:opacity-50"
          >
            {busy ? '…' : `✓ ${L('Picked Up', 'తీసుకువెళ్ళారు')}`}
          </button>
        )}
      </div>
    )
  }

  return (
    <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
      <div className="px-4 pt-4 pb-3 flex items-center justify-between border-b border-gray-100 gap-2">
        <h2 className="font-extrabold text-gray-900 text-base leading-tight">
          📅 {L("Today's Schedule", 'నేటి షెడ్యూల్')}
        </h2>
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value || todayStr)}
          className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs bg-white focus:border-green-500 focus:outline-none"
        />
      </div>

      <div className="p-4 space-y-4">
        {loading ? (
          <p className="text-sm text-gray-400 text-center py-4">{tx.loadingLabel}</p>
        ) : orders.length === 0 ? (
          <p className="text-sm text-gray-400 text-center py-4">{L('Nothing scheduled for this date', 'ఈ తేదీకి ఏమీ లేదు')}</p>
        ) : (
          <>
            <div>
              <p className="text-xs font-bold text-green-800 uppercase tracking-wide mb-2">
                🧺 {L('Pickups', 'పికప్‌లు')} ({pickups.length})
              </p>
              {pickups.length === 0 ? (
                <p className="text-xs text-gray-400">{L('No pickups', 'పికప్‌లు లేవు')}</p>
              ) : (
                <div className="space-y-2">{pickups.map((o) => <Row key={o.id} o={o} />)}</div>
              )}
            </div>
            <div>
              <p className="text-xs font-bold text-blue-800 uppercase tracking-wide mb-2">
                🛵 {L('Deliveries', 'డెలివరీలు')} ({deliveries.length})
              </p>
              {deliveries.length === 0 ? (
                <p className="text-xs text-gray-400">{L('No deliveries', 'డెలివరీలు లేవు')}</p>
              ) : (
                <div className="space-y-2">{deliveries.map((o) => <Row key={o.id} o={o} />)}</div>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

